"""037 additions derived from contract formulas; imports run only after explicit call."""
def extend(add,CAT):
 def put(id,old,new,label=None,why='契约逐项规定的输出被常量替代；只恢复这一处表达式，其他输出与上游保持agent原代码。'):
  add(id,label or old.split()[-1],old,new,why)
 id='impl-001_int_lever__posting_analytics'
 src='FROM staging.stg_lever__application aa JOIN staging.stg_lever__interview ii ON aa.opportunity_id=ii.opportunity_id LEFT JOIN staging.stg_lever__interviewer_user iu ON ii.interview_id=iu.interview_id WHERE aa.posting_id=p.posting_id'
 vals={'total_interviews_scheduled':('0::BIGINT','count(DISTINCT ii.interview_id)'), 'completed_interviews':('0::BIGINT','count(DISTINCT ii.interview_id) FILTER(WHERE ii.canceled_at IS NULL)'), 'unique_interviewers':('0::BIGINT','count(DISTINCT iu.user_id)'), 'avg_interview_duration_minutes':('0.0','coalesce(avg(ii.duration),0)'), 'total_interview_time_minutes':('0.0','coalesce(sum(ii.duration),0)'), 'interview_completion_rate_pct':('0.0','CASE WHEN count(DISTINCT ii.interview_id)>0 THEN round(count(DISTINCT ii.interview_id) FILTER(WHERE ii.canceled_at IS NULL)*100.0/count(DISTINCT ii.interview_id),1) ELSE 0 END')}
 for col,(old,expr) in vals.items():put(id,f'{old} {col}',f'(SELECT {expr} {src}) {col}')
 put(id,"'No Applications' performance_tier","CASE WHEN total_applications>=20 AND candidates_hired>=2 AND avg_days_to_advancement<=45 THEN 'High Performing' WHEN total_applications>=10 AND candidates_hired>=1 AND avg_days_to_advancement<=60 THEN 'Good Performing' WHEN total_applications>=5 THEN 'Moderate Performing' WHEN total_applications>=1 THEN 'Low Performing' ELSE 'No Applications' END performance_tier")
 put(id,'0::BIGINT posting_effectiveness_score','least(100,greatest(0,round(least(20,total_applications)+CASE WHEN candidates_hired>0 THEN 25 ELSE 0 END+CASE WHEN avg_days_to_advancement<=30 THEN 20 WHEN avg_days_to_advancement<=60 THEN 10 ELSE 0 END+CASE WHEN interview_completion_rate_pct>=80 THEN 15 ELSE 5 END+CASE WHEN referral_rate_pct>=20 THEN 10 WHEN referral_rate_pct>=10 THEN 5 ELSE 0 END+CASE WHEN offer_acceptance_rate_pct>=70 THEN 10 ELSE 0 END,0))) posting_effectiveness_score')
 put(id,"'No Major Issues' primary_bottleneck","CASE WHEN total_applications=0 THEN 'No Attraction - Poor Job Posting' WHEN interview_completion_rate_pct<70 THEN 'Interview Scheduling Issues' WHEN offer_acceptance_rate_pct<60 AND offers_extended>0 THEN 'Low Offer Acceptance' WHEN avg_days_to_advancement>60 THEN 'Slow Decision Process' WHEN candidates_hired=0 AND total_applications>=10 THEN 'High Standards or Poor Fit' ELSE 'No Major Issues' END primary_bottleneck")
 id='impl-001_int_lever__posting_performance'
 base='FROM staging.stg_lever__application aa LEFT JOIN staging.stg_lever__opportunity oo ON aa.opportunity_id=oo.opportunity_id LEFT JOIN staging.stg_lever__contact_email ce ON oo.contact_id=ce.contact_id LEFT JOIN staging.stg_lever__contact_phone cp ON oo.contact_id=cp.contact_id LEFT JOIN staging.stg_lever__resume rr ON aa.opportunity_id=rr.opportunity_id LEFT JOIN staging.stg_lever__interview ii ON aa.opportunity_id=ii.opportunity_id WHERE aa.posting_id=p.posting_id'
 interview="oo.stage_id IN (SELECT stage_id FROM staging.stg_lever__stage WHERE lower(stage_name) LIKE '%interview%' OR lower(stage_name) LIKE '%technical%' OR lower(stage_name) LIKE '%onsite%')"
 vals={'candidates_reached_interview':('0::BIGINT',f'count(DISTINCT aa.opportunity_id) FILTER(WHERE {interview})'), 'candidates_with_email':('0::BIGINT','count(DISTINCT aa.opportunity_id) FILTER(WHERE ce.email IS NOT NULL)'), 'candidates_with_phone':('0::BIGINT','count(DISTINCT aa.opportunity_id) FILTER(WHERE cp.phone_number IS NOT NULL)'), 'candidates_with_resume':('0::BIGINT','count(DISTINCT aa.opportunity_id) FILTER(WHERE rr.resume_id IS NOT NULL)'), 'total_interviews_scheduled':('0::BIGINT','count(DISTINCT ii.interview_id)'), 'completed_interviews':('0::BIGINT','count(DISTINCT ii.interview_id) FILTER(WHERE ii.canceled_at IS NULL)'), 'interview_completion_rate':('0.0','coalesce(round(count(DISTINCT ii.interview_id) FILTER(WHERE ii.canceled_at IS NULL)*100.0/nullif(count(DISTINCT ii.interview_id),0),1),0)'), 'application_to_interview_rate':('0.0',f'coalesce(round(count(DISTINCT aa.opportunity_id) FILTER(WHERE {interview})*100.0/nullif(count(DISTINCT aa.application_id),0),2),0)')}
 for col,(old,expr) in vals.items():put(id,f'{old} {col}',f'(SELECT {expr} {base}) {col}')
 put(id,"'No Applications' performance_tier","CASE WHEN total_applications=0 THEN 'No Applications' WHEN total_applications<5 THEN 'Low Volume' WHEN candidates_hired>0 AND total_applications>=10 THEN 'High Performing' WHEN candidates_reached_offer>0 AND total_applications>=5 THEN 'Moderate Performing' WHEN candidates_reached_interview>0 THEN 'Building Pipeline' ELSE 'Needs Attention' END performance_tier")
 put(id,'NULL::DOUBLE posting_performance_score','CASE WHEN total_applications>=5 THEN round(least(25,total_applications*1.25)+CASE WHEN candidates_hired>0 THEN 25 ELSE 0 END+least(25,candidates_reached_interview*100.0/total_applications)+CASE WHEN interview_completion_rate>=80 THEN 25 ELSE interview_completion_rate*.3125 END,1) END posting_performance_score')
 put(id,"'Unknown Status' posting_status_analysis","CASE WHEN any_value(p.state)='published' AND active_candidates_30d>0 THEN 'Active & Engaging' WHEN any_value(p.state)='published' AND total_applications>0 THEN 'Published with Interest' WHEN any_value(p.state)='published' THEN 'Published but No Interest' WHEN any_value(p.state)='closed' AND candidates_hired>0 THEN 'Successfully Filled' WHEN any_value(p.state)='closed' THEN 'Closed without Hire' ELSE 'Unknown Status' END posting_status_analysis")
 id='impl-001_lever__departmental_hiring_trends'
 base="FROM staging.stg_lever__posting p2 LEFT JOIN staging.stg_lever__application aa ON p2.posting_id=aa.posting_id LEFT JOIN staging.stg_lever__interview ii ON aa.opportunity_id=ii.opportunity_id LEFT JOIN staging.stg_lever__interviewer_user iu ON ii.interview_id=iu.interview_id LEFT JOIN staging.stg_lever__interview_feedback fb ON ii.interview_id=fb.interview_id WHERE coalesce(p2.categories_department,'Unknown Department')=b.department AND coalesce(p2.categories_team,'Unknown Team')=b.team"
 for col,old,expr in [('total_interviews_conducted','0::BIGINT','count(DISTINCT ii.interview_id)'),('unique_interviewers','0::BIGINT','count(DISTINCT iu.user_id)'),('avg_interview_duration_minutes','0.0','coalesce(avg(ii.duration),0)'),('interview_completion_rate','0.0','coalesce(round(count(DISTINCT ii.interview_id) FILTER(WHERE ii.canceled_at IS NULL)*100.0/nullif(count(DISTINCT ii.interview_id),0),2),0)')]:put(id,f'{old} AS {col}',f'(SELECT {expr} {base}) AS {col}')
 base="FROM staging.stg_lever__posting p2 LEFT JOIN staging.stg_lever__application aa ON p2.posting_id=aa.posting_id LEFT JOIN marts.lever__candidate_experience_insights cei ON aa.opportunity_id=cei.opportunity_id LEFT JOIN intermediate.int_lever__hiring_funnel_metrics hfm ON p2.posting_id=hfm.posting_id WHERE coalesce(p2.categories_department,'Unknown Department')=b.department AND coalesce(p2.categories_team,'Unknown Team')=b.team"
 for col,old,expr in [('avg_candidate_experience_score','0.0','coalesce(avg(cei.overall_candidate_experience_score),0)'),('avg_screening_pass_rate','0.0','coalesce(avg(hfm.application_to_screening_rate),0)'),('high_efficiency_postings','0::BIGINT',"count(DISTINCT p2.posting_id) FILTER(WHERE hfm.hiring_efficiency_grade='High Efficiency (≥10%)')")]:put(id,f'{old} AS {col}',f'(SELECT {expr} {base}) AS {col}')
